<?php require __DIR__.'/../app/bootstrap.php';require_login();require_permission('reports.export');$type=$_GET['type']??'units';$map=[
'units'=>['SELECT unit_code,unit_name,category,brand,model,location,meter_type,current_meter,operational_status FROM units ORDER BY unit_code','unit'],
'service'=>["SELECT u.unit_code,u.current_meter,ss.next_service_meter,ss.next_service_date,ss.status,ss.notes FROM service_schedules ss JOIN units u ON u.id=ss.unit_id ORDER BY ss.next_service_date",'service'],
'logistics'=>["SELECT request_no,item_name,quantity,vendor,order_date,expected_date,status,approval_status,total_cost FROM logistics_orders ORDER BY id DESC",'logistik'],
'analytics'=>["SELECT u.unit_code,u.location,u.current_meter,u.meter_type,COALESCE(SUM(m.actual_cost),0) total_cost,CASE WHEN u.current_meter>0 THEN COALESCE(SUM(m.actual_cost),0)/u.current_meter ELSE 0 END cost_per_meter FROM units u LEFT JOIN maintenance_orders m ON m.unit_id=u.id GROUP BY u.id",'kpi']];if(!isset($map[$type]))$type='units';[$sql,$name]=$map[$type];$rows=$pdo->query($sql)->fetchAll();audit($pdo,'EXPORT','report',null,'Excel '.$type);header('Content-Type: application/vnd.ms-excel; charset=utf-8');header('Content-Disposition: attachment; filename="assetpro_'.$name.'_'.date('Ymd_His').'.xls"');echo '<html><head><meta charset="utf-8"></head><body><table border="1">';if($rows){echo '<tr>';foreach(array_keys($rows[0]) as $h)echo '<th>'.e($h).'</th>';echo '</tr>';foreach($rows as $r){echo '<tr>';foreach($r as $v)echo '<td>'.e((string)$v).'</td>';echo '</tr>';}}echo '</table></body></html>';
